def count_pairs_within(prices, budget):
    lo, hi = 0, len(prices) - 1
    count = 0
    while lo < hi:
        if prices[lo] + prices[hi] <= budget:
            count += hi - lo
            lo += 1
        else:
            hi -= 1
    return count
